function buildTopology() {
  const fullTaxa = buildFull180Dataset();
  nodes = [];
  edges = [];

  fullTaxa.forEach((tData, idx) => {
    const imgObj = getPreloadedImage(tData.img, tData.id, tData.name, tData.cat);

    const phi = Math.acos(1 - 2 * ((idx + 0.5) / fullTaxa.length));
    const theta = Math.PI * (1 + Math.sqrt(5)) * idx;

    const rad = tData.cat === 4 ? 290 : (tData.cat === 0 ? 180 + (idx % 4) * 25 : 230);
    const nx = rad * Math.sin(phi) * Math.cos(theta);
    const ny = rad * Math.sin(phi) * Math.sin(theta);
    const nz = rad * Math.cos(phi);

    const nodeId = nodes.length;
    nodes.push({
      id: nodeId, taxaId: tData.id, label: tData.name, sciname: tData.sciname, cat: tData.cat, role: tData.role, loc: tData.loc, alert: tData.alert, photoUrl: tData.img || generateSpeciesSvgDataUri(tData.id, tData.name, tData.cat), imgObj,
      x: nx, y: ny, z: nz, ox: nx, oy: ny, oz: nz, level: tData.cat === 0 ? 1 : 2, hiddenByUser: false
    });
  });

  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const a = nodes[i];
      const b = nodes[j];
      if (a.cat === b.cat || (a.cat === 0 && b.cat === 1) || (a.cat === 0 && b.cat === 3) || (a.cat === 1 && b.cat === 3)) {
        const dist = Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
        if (dist < 140 && Math.random() < 0.35) {
          edges.push({ source: a.id, target: b.id });
        }
      }
    }
  }

  recalculateDegreesAndSizes();
}

