function buildTopology() {
  const fullTaxa = buildFull180Dataset();

  // Shuffle taxa deterministically so category groups (Flora, Avifauna, Micro, Herpetos) are 100% mixed throughout the 3D space
  const shuffledTaxa = [...fullTaxa];
  for (let i = shuffledTaxa.length - 1; i > 0; i--) {
    const j = (i * 37 + 13) % (i + 1);
    [shuffledTaxa[i], shuffledTaxa[j]] = [shuffledTaxa[j], shuffledTaxa[i]];
  }

  nodes = [];
  edges = [];

  shuffledTaxa.forEach((tData, idx) => {
    const imgObj = getPreloadedImage(tData.img, tData.id, tData.name, tData.cat);

    // Uniform 3D Fibonacci Sphere distribution with random radius variation for a 100% organic blended swarm
    const phi = Math.acos(1 - 2 * ((idx + 0.5) / shuffledTaxa.length));
    const theta = Math.PI * (1 + Math.sqrt(5)) * idx;
    const rad = 170 + ((idx * 17) % 110);

    const nx = rad * Math.sin(phi) * Math.cos(theta);
    const ny = rad * Math.sin(phi) * Math.sin(theta);
    const nz = rad * Math.cos(phi);

    const nodeId = nodes.length;
    nodes.push({
      id: nodeId, taxaId: tData.id, label: tData.name, sciname: tData.sciname, cat: tData.cat, role: tData.role, loc: tData.loc, alert: tData.alert, photoUrl: tData.img || generateSpeciesSvgDataUri(tData.id, tData.name, tData.cat), imgObj,
      x: nx, y: ny, z: nz, ox: nx, oy: ny, oz: nz, level: 1, hiddenByUser: false
    });
  });

  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const a = nodes[i];
      const b = nodes[j];
      const dist = Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
      // Inter-category and intra-category biological interactions across nearby nodes
      if (dist < 135 && Math.random() < 0.32) {
        edges.push({ source: a.id, target: b.id });
      }
    }
  }

  recalculateDegreesAndSizes();
}

