function setLayout(mode) {
  opts.layoutMode = mode;
  nodes.forEach((n, idx) => {
    if (mode === 'clustered') {
      const catAngle = ((idx * 7) % nodes.length / nodes.length) * Math.PI * 2;
      const r = 140 + (idx % 25) * 5;
      n.ox = Math.cos(catAngle) * r + (Math.random() - 0.5) * 40;
      n.oy = (Math.random() - 0.5) * 90;
      n.oz = Math.sin(catAngle) * r + (Math.random() - 0.5) * 40;
    } else if (mode === 'concentric') {
      const r = 120 + (idx % 5) * 40;
      const a = idx * 0.17;
      n.ox = Math.cos(a) * r;
      n.oy = (idx % 7) * 16 - 48;
      n.oz = Math.sin(a) * r;
    } else if (mode === 'hyperbolic') {
      const phi = Math.acos(1 - 2 * ((idx + 0.5) / nodes.length));
      const theta = Math.PI * (1 + Math.sqrt(5)) * idx;
      const rad = 170 + ((idx * 17) % 110);
      n.ox = rad * Math.sin(phi) * Math.cos(theta);
      n.oy = rad * Math.sin(phi) * Math.sin(theta);
      n.oz = rad * Math.cos(phi);
    }
  });
}

