      const catAngle = (n.cat / 6) * Math.PI * 2;
      const r = 160 + (idx % 20) * 4;
      n.ox = Math.cos(catAngle) * r + (Math.random() - 0.5) * 30;
      n.oy = (Math.random() - 0.5) * 80;
      n.oz = Math.sin(catAngle) * r + (Math.random() - 0.5) * 30;
    } else if (mode === 'concentric') {
      const r = (n.cat + 1) * 45;
      const a = idx * 0.15;
      n.ox = Math.cos(a) * r;
      n.oy = (idx % 5) * 15 - 30;
      n.oz = Math.sin(a) * r;
    } else if (mode === 'hyperbolic') {
      const phi = Math.acos(1 - 2 * (idx / nodes.length));
      const theta = Math.PI * (1 + Math.sqrt(5)) * idx;
      const rad = n.cat === 4 ? 290 : (n.cat === 0 ? 180 + (idx % 4) * 25 : 230);
      n.ox = rad * Math.sin(phi) * Math.cos(theta);
      n.oy = rad * Math.sin(phi) * Math.sin(theta);
      n.oz = rad * Math.cos(phi);
    }
  });
}

