  // Expanded 3D Fibonacci Sphere distribution ensuring strict spatial clearance (minimum 45px distance between any 2 nodes)
  const phi = Math.acos(1 - 2 * ((idx + 0.5) / shuffledTaxa.length));
  const theta = Math.PI * (1 + Math.sqrt(5)) * idx;
  const rad = 220 + ((idx * 23) % 130);

  const nx = rad * Math.sin(phi) * Math.cos(theta);
  const ny = rad * Math.sin(phi) * Math.sin(theta);
  const nz = rad * Math.cos(phi);

  const nodeId = nodes.length;
  nodes.push({
