function renderSubNetworkCanvas() {
  const subCanvas = document.getElementById('subCanvas');
  const wrap = subCanvas.parentElement;
  subCanvas.width = wrap.clientWidth;
  subCanvas.height = wrap.clientHeight;
  const sctx = subCanvas.getContext('2d');

  const centerNode = selectedNode;
  // Filter neighbors based on sub-network active layer toggles
  const neighbors = (centerNode.neighbors || []).filter(nb => subOpts.cats[nb.cat] !== false);

  // Organic 2D Mesh Network layout (No linear axis, no cross alignments)
  const cx = subCanvas.width / 2;
  const cy = subCanvas.height / 2;

  // Dynamic degree calculation for the active sub-network view
  const activeSubDegree = neighbors.length;
  const centerTargetSize = Math.min(32, Math.max(18, 14 + Math.sqrt(activeSubDegree) * 2.8));

  const subNodes = [
    { ...centerNode, sx: cx, sy: cy, isCenter: true, targetSize: centerTargetSize, activeDegree: activeSubDegree }
  ];

  const totalNb = neighbors.length;
  neighbors.forEach((nb, idx) => {
    // Golden Ratio organic spiral distribution to prevent any 4-way cross or linear patterns
    const angle = idx * 2.39996 + 0.4; // Golden angle offset
    const distRatio = Math.sqrt((idx + 1) / Math.max(1, totalNb));
    const subRadius = 90 + distRatio * (Math.min(cx, cy) - 130);

    const nx = cx + Math.cos(angle) * subRadius;
    const ny = cy + Math.sin(angle) * subRadius * 0.85; // Slight organic ellipse

    // Recalculate neighbor active sub-degree considering layer toggles
    const nbActiveDegree = (nb.neighbors || []).filter(nnb => subOpts.cats[nnb.cat] !== false).length;
    const nbTargetSize = Math.min(24, Math.max(12, 10 + Math.sqrt(nbActiveDegree) * 1.8));

    subNodes.push({ ...nb, sx: nx, sy: ny, isCenter: false, angle, targetSize: nbTargetSize, activeDegree: nbActiveDegree });
  });

  const interactionTypes = [
    { name: 'Depredación', color: '#ff0033' },
    { name: 'Herbivoría', color: '#00ff88' },
    { name: 'Dispersión', color: '#ff80a0' },
    { name: 'Mutualismo', color: '#ffee33' },
    { name: 'Nidificación', color: '#ffaa00' },
    { name: 'Visita Floral', color: '#d000ff' },
    { name: 'Anidamiento', color: '#a0522d' },
    { name: 'Parasitismo', color: '#ffff00' },
    { name: 'Alelopatía', color: '#888888' }
  ];

  function drawSub() {
    sctx.fillStyle = '#020408';
    sctx.fillRect(0, 0, subCanvas.width, subCanvas.height);

    // Draw Sub-Network Edges with specific interaction colors
    neighbors.forEach((nb, idx) => {
      const targetSub = subNodes[idx + 1];

      let inter = interactionTypes[0];
      if (centerNode.cat === 0 && nb.cat === 1) inter = interactionTypes[5];
      else if (centerNode.cat === 1 && nb.cat === 0) inter = interactionTypes[2];
      else if (centerNode.cat === 1 && nb.cat === 3) inter = interactionTypes[0];
      else if (centerNode.cat === 3 && nb.cat === 0) inter = interactionTypes[1];
      else if (centerNode.cat === 0 && nb.cat === 0) inter = interactionTypes[8];
      else if (centerNode.cat === 2) inter = interactionTypes[3];
      else inter = interactionTypes[(idx + centerNode.id) % interactionTypes.length];

      // Draw Glowing Edge
      sctx.save();
      sctx.beginPath();
      sctx.moveTo(cx, cy);
      sctx.lineTo(targetSub.sx, targetSub.sy);
      sctx.strokeStyle = inter.color;
      sctx.lineWidth = 2.5;
      sctx.shadowColor = inter.color;
      sctx.shadowBlur = 8;
      sctx.stroke();
      sctx.restore();

      // Edge Label (Type)
      const mx = (cx + targetSub.sx) / 2;
      const my = (cy + targetSub.sy) / 2;
      sctx.save();
      sctx.font = '9px ui-monospace, monospace';
      sctx.fillStyle = '#ffffff';
      sctx.shadowColor = '#000000';
      sctx.shadowBlur = 4;
      sctx.fillText(inter.name, mx - 15, my - 4);
      sctx.restore();
    });

    // Draw Sub-Network Nodes
    subNodes.forEach(sn => {
      const r = sn.targetSize;

      sctx.save();
      sctx.beginPath();
      sctx.arc(sn.sx, sn.sy, r, 0, Math.PI * 2);
      sctx.clip();

      if (sn.imgObj && sn.imgObj.complete && sn.imgObj.naturalWidth !== 0) {
        sctx.drawImage(sn.imgObj, sn.sx - r, sn.sy - r, r * 2, r * 2);
      } else {
        sctx.fillStyle = palette.catColors[sn.cat] || '#00ffff';
        sctx.fillRect(sn.sx - r, sn.sy - r, r * 2, r * 2);
      }
      sctx.restore();

      // Border Ring
      sctx.save();
      sctx.beginPath();
      sctx.arc(sn.sx, sn.sy, r + 1, 0, Math.PI * 2);
      sctx.strokeStyle = sn.isCenter ? '#00ffff' : palette.catColors[sn.cat];
      sctx.lineWidth = sn.isCenter ? 3.5 : 2;
      if (sn.isCenter) {
        sctx.shadowColor = '#00ffff';
        sctx.shadowBlur = 12;
      }
      sctx.stroke();
      sctx.restore();

      // Node Text Label
      sctx.save();
      sctx.font = sn.isCenter ? '11px monospace' : '9.5px monospace';
      sctx.fillStyle = '#ffffff';
      sctx.shadowColor = '#000000';
      sctx.shadowBlur = 4;
      sctx.fillText(`${sn.label} [${sn.taxaId}] (k=${sn.activeDegree})`, sn.sx + r + 6, sn.sy + 4);
      sctx.restore();
    });
  }

  drawSub();

  // Click event inside Sub-Network canvas to switch focus to neighbor
  subCanvas.onclick = (e) => {
    const rect = subCanvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    subNodes.forEach(sn => {
      const r = sn.isCenter ? 26 : 20;
      if (Math.hypot(sn.sx - mx, sn.sy - my) < r) {
        if (!sn.isCenter) {
          closeSubNetworkModal();
          openInspector(nodes[sn.id]);
        }
      }
    });
  };
}

