  targets.set(centerNode.id, {
    targetSx: cx,
    targetSy: cy,
    targetSize: Math.min(32, Math.max(18, 14 + Math.sqrt(totalActive) * 2.8)),
    activeDegree: totalActive,
    isCenter: true
  });

  activeNeighbors.forEach((nb, idx) => {
    const angle = idx * 2.39996 + 0.4;
    const distRatio = Math.sqrt((idx + 1) / Math.max(1, totalActive));
    const subRadius = 90 + distRatio * (Math.min(cx, cy) - 130);

    const targetSx = cx + Math.cos(angle) * subRadius;
    const targetSy = cy + Math.sin(angle) * subRadius * 0.85;

    const nbActiveDegree = (nb.neighbors || []).filter(nnb => subOpts.cats[nnb.cat] !== false).length;
    const targetSize = Math.min(24, Math.max(12, 10 + Math.sqrt(nbActiveDegree) * 1.8));

    targets.set(nb.id, {
      targetSx,
      targetSy,
      targetSize,
      activeDegree: nbActiveDegree,
      isCenter: false
    });
  });

