      if (centerNode.cat === 0 && sn.cat === 1) inter = interactionTypes[5];
      else if (centerNode.cat === 1 && sn.cat === 0) inter = interactionTypes[2];
      else if (centerNode.cat === 1 && sn.cat === 3) inter = interactionTypes[0];
      else if (centerNode.cat === 3 && sn.cat === 0) inter = interactionTypes[1];
      else if (centerNode.cat === 0 && sn.cat === 0) inter = interactionTypes[8];
      else if (centerNode.cat === 2) inter = interactionTypes[3];
      else inter = interactionTypes[(idx + centerNode.id) % interactionTypes.length];

      if (centerSub) {
        sctx.save();
        sctx.beginPath();
        sctx.moveTo(centerSub.sx, centerSub.sy);
        sctx.lineTo(sn.sx, sn.sy);
        sctx.strokeStyle = inter.color;
        sctx.lineWidth = 2.5;
        sctx.shadowColor = inter.color;
        sctx.shadowBlur = 8;
        sctx.stroke();
        sctx.restore();

        const mx = (centerSub.sx + sn.sx) / 2;
        const my = (centerSub.sy + sn.sy) / 2;
        sctx.save();
        sctx.font = '9px ui-monospace, monospace';
        sctx.fillStyle = '#ffffff';
        sctx.shadowColor = '#000000';
        sctx.shadowBlur = 4;
        sctx.fillText(inter.name, mx - 15, my - 4);
        sctx.restore();
      }
    });

    // Draw Sub-Network Nodes
    subState.nodes.forEach(sn => {
      const r = sn.currentSize;

      sctx.save();
      sctx.beginPath();
      sctx.arc(sn.sx, sn.sy, r, 0, Math.PI * 2);
      sctx.clip();

      if (sn.imgObj && sn.imgObj.complete && sn.imgObj.naturalWidth !== 0) {
        sctx.drawImage(sn.imgObj, sn.sx - r, sn.sy - r, r * 2, r * 2);
      } else {
        sctx.fillStyle = palette.catColors[sn.cat] || '#00ffff';
        sctx.fillRect(sn.sx - r, sn.sy - r, r * 2, r * 2);
      }
      sctx.restore();

      // Border Ring
      sctx.save();
      sctx.beginPath();
      sctx.arc(sn.sx, sn.sy, r + 1, 0, Math.PI * 2);
      sctx.strokeStyle = sn.isCenter ? '#00ffff' : palette.catColors[sn.cat];
      sctx.lineWidth = sn.isCenter ? 3.5 : 2;
      if (sn.isCenter) {
        sctx.shadowColor = '#00ffff';
        sctx.shadowBlur = 12;
      }
      sctx.stroke();
      sctx.restore();

      // Node Text Label
      sctx.save();
      sctx.font = sn.isCenter ? '11px monospace' : '9.5px monospace';
      sctx.fillStyle = '#ffffff';
      sctx.shadowColor = '#000000';
      sctx.shadowBlur = 4;
      sctx.fillText(`${sn.label} [${sn.taxaId}] (k=${sn.activeDegree})`, sn.sx + r + 6, sn.sy + 4);
      sctx.restore();
    });

    subCanvasAnim = requestAnimationFrame(loopSub);
  }

  loopSub();

  // Click event inside Sub-Network canvas to switch focus to neighbor
  subCanvas.onclick = (e) => {
    const rect = subCanvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    subState.nodes.forEach(sn => {
      const r = sn.currentSize || 20;
      if (Math.hypot(sn.sx - mx, sn.sy - my) < r) {
        if (!sn.isCenter) {
          closeSubNetworkModal();
          openInspector(nodes[sn.id]);
        }
      }
    });
  };
}

