// High-Tech Scientific Badge Generator for nodes (Strictly NO ICONS or visual symbols)
function generateSpeciesSvgDataUri(taxonId, speciesName, cat) {
  const colors = {
    0: ['#003318', '#00ff88', '#10B981'], // Flora
    1: ['#002233', '#00ffff', '#38BDF8'], // Avifauna
    2: ['#33001a', '#ff007f', '#F43F5E'], // Micro
    3: ['#332c00', '#ffee33', '#FACC15'], // Herpetos / MIA
    4: ['#33000a', '#ff0033', '#EF4444'], // Abióticos
    5: ['#332200', '#ffaa00', '#F59E0B']  // Core
  };
  const c = colors[cat] || colors[0];
  const initials = taxonId.split('-')[0];
  const codeNum = taxonId.split('-')[1] || '';

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 64 64">
    <rect width="64" height="64" rx="32" fill="${c[0]}"/>
    <circle cx="32" cy="32" r="29" stroke="${c[1]}" stroke-width="2" fill="none" opacity="0.8"/>
    <circle cx="32" cy="32" r="23" stroke="${c[1]}" stroke-width="1" stroke-dasharray="2,2" fill="none" opacity="0.4"/>
    <text x="32" y="28" font-family="ui-monospace, monospace" font-size="10" font-weight="900" fill="${c[1]}" text-anchor="middle" letter-spacing="0.5">${initials}</text>
    <text x="32" y="42" font-family="ui-monospace, monospace" font-size="12" font-weight="bold" fill="#ffffff" text-anchor="middle">${codeNum}</text>
  </svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

const imageCache = {};

function getPreloadedImage(url, taxonId, speciesName, cat) {
  const srcUrl = url || generateSpeciesSvgDataUri(taxonId, speciesName, cat);
  if (imageCache[srcUrl]) return imageCache[srcUrl];

  const img = new Image();
  img.crossOrigin = 'Anonymous';
  img.src = srcUrl;
  // Fallback if external image fails to load
  img.onerror = () => {
    img.src = generateSpeciesSvgDataUri(taxonId, speciesName, cat);
  };
  imageCache[srcUrl] = img;
  return img;
}

