function toggleSubCat(catId) {
  subOpts.cats[catId] = !subOpts.cats[catId];
  const btn = document.getElementById(`subToggle${catId}`);
  if (btn) btn.classList.toggle('active', subOpts.cats[catId]);
  renderSubNetworkCanvas();
}

function openSubNetworkModal() {
  if (!selectedNode) return;
  const subModal = document.getElementById('subnetworkModal');
  document.getElementById('subModalTitle').innerText = `Sub-Red Directa: ${selectedNode.label}`;
  document.getElementById('subModalCode').innerText = `[${selectedNode.taxaId}]`;
  subModal.style.display = 'flex';
  renderSubNetworkCanvas();
}

function closeSubNetworkModal() {
  document.getElementById('subnetworkModal').style.display = 'none';
  if (subCanvasAnim) cancelAnimationFrame(subCanvasAnim);
}

let subState = {
  nodes: [],
  links: []
};

function renderSubNetworkCanvas() {
  if (subCanvasAnim) cancelAnimationFrame(subCanvasAnim);

  const subCanvas = document.getElementById('subCanvas');
  const wrap = subCanvas.parentElement;
  subCanvas.width = wrap.clientWidth;
  subCanvas.height = wrap.clientHeight;
  const sctx = subCanvas.getContext('2d');

  const centerNode = selectedNode;
  if (!centerNode) return;

  const cx = subCanvas.width / 2;
  const cy = subCanvas.height / 2;

  // Filter neighbors strictly based on active layer category toggles and active state
  const activeNeighbors = (centerNode.neighbors || []).filter(nb => nb.active && subOpts.cats[nb.cat] !== false);
  const totalActive = activeNeighbors.length;

  // Target layout calculation using golden angle mesh
  const targets = new Map();

  // Center node target calculation
  targets.set(centerNode.id, {
    targetSx: cx,
    targetSy: cy,
    targetSize: Math.min(34, Math.max(18, 14 + Math.sqrt(totalActive) * 3.0)),
    activeDegree: totalActive,
    isCenter: true
  });

  activeNeighbors.forEach((nb, idx) => {
    const angle = idx * 2.39996 + 0.4;
    const distRatio = Math.sqrt((idx + 1) / Math.max(1, totalActive));
    const subRadius = 90 + distRatio * (Math.min(cx, cy) - 130);

    const targetSx = cx + Math.cos(angle) * subRadius;
    const targetSy = cy + Math.sin(angle) * subRadius * 0.85;

    // Recalculate neighbor degree against visible sub-network layers
    const nbActiveDegree = (nb.neighbors || []).filter(nnb => nnb.active && subOpts.cats[nnb.cat] !== false).length;
    const targetSize = Math.min(26, Math.max(12, 10 + Math.sqrt(nbActiveDegree) * 2.0));

    targets.set(nb.id, {
      targetSx,
      targetSy,
      targetSize,
      activeDegree: nbActiveDegree,
      isCenter: false
    });
  });

  // Synchronize subState nodes: ONLY keep nodes that exist in current active targets
  const existingMap = new Map(subState.nodes.map(n => [n.id, n]));
  const newSubNodes = [];

  targets.forEach((t, id) => {
    const fullObj = id === centerNode.id ? centerNode : nodes[id];
    let existing = existingMap.get(id);

    if (!existing) {
      existing = {
        ...fullObj,
        sx: t.isCenter ? cx : cx + (Math.random() - 0.5) * 40,
        sy: t.isCenter ? cy : cy + (Math.random() - 0.5) * 40,
        currentSize: 4, // start small for morphing
        targetSx: t.targetSx,
        targetSy: t.targetSy,
        targetSize: t.targetSize,
        activeDegree: t.activeDegree,
        isCenter: t.isCenter
      };
    } else {
      existing.targetSx = t.targetSx;
      existing.targetSy = t.targetSy;
      existing.targetSize = t.targetSize;
      existing.activeDegree = t.activeDegree;
      existing.isCenter = t.isCenter;
    }
    newSubNodes.push(existing);
  });

  subState.nodes = newSubNodes;

