// Multi-hub organic layout calculation: group sub-nodes into 4 decentralized category clusters
const targets = new Map();
const clusterCenters = {
  0: { angle: -Math.PI * 0.75, dist: Math.min(cx, cy) * 0.52 }, // Flora Cluster
  1: { angle: -Math.PI * 0.15, dist: Math.min(cx, cy) * 0.52 }, // Avifauna Cluster
  2: { angle: Math.PI * 0.65, dist: Math.min(cx, cy) * 0.52 },  // Microorganismos Cluster
  3: { angle: Math.PI * 0.25, dist: Math.min(cx, cy) * 0.52 }   // Fauna Cluster
};

// Center focal node target calculation
targets.set(centerNode.id, {
  targetSx: cx,
  targetSy: cy,
  targetSize: Math.min(34, Math.max(18, 14 + Math.sqrt(totalActive) * 3.0)),
  activeDegree: totalActive,
  isCenter: true
});

// Group neighbors by category for cluster dispersion
const catGroups = { 0: [], 1: [], 2: [], 3: [] };
activeNeighbors.forEach((nb, idx) => {
  const cat = nb.cat !== undefined ? nb.cat : 0;
  if (!catGroups[cat]) catGroups[cat] = [];
  catGroups[cat].push({ nb, idx });
});

Object.keys(catGroups).forEach(catKey => {
  const group = catGroups[catKey];
  const cluster = clusterCenters[catKey] || { angle: 0, dist: Math.min(cx, cy) * 0.4 };
  const hubCx = cx + Math.cos(cluster.angle) * cluster.dist;
  const hubCy = cy + Math.sin(cluster.angle) * cluster.dist * 0.85;

  group.forEach((item, gIdx) => {
    const { nb, idx } = item;
    const spreadAngle = (gIdx - (group.length - 1) / 2) * 0.45;
    const offsetRadius = 35 + (gIdx % 3) * 22;

    const targetSx = hubCx + Math.cos(cluster.angle + spreadAngle) * offsetRadius;
    const targetSy = hubCy + Math.sin(cluster.angle + spreadAngle) * offsetRadius * 0.85;

    const nbActiveDegree = (nb.neighbors || []).filter((nnb, nidx) => {
      if (!nnb.active) return false;
      const tId = getInteractionType(nb, nnb, nidx);
      return subOpts.interactions[tId] !== false;
    }).length;

    const targetSize = Math.min(26, Math.max(12, 10 + Math.sqrt(nbActiveDegree) * 2.0));

    targets.set(nb.id, {
      targetSx,
      targetSy,
      targetSize,
      activeDegree: nbActiveDegree,
      isCenter: false,
      interType: getInteractionType(centerNode, nb, idx)
    });
  });
});

// Synchronize subState nodes: ONLY keep nodes that exist in current active targets
const existingMap = new Map(subState.nodes.map(n => [n.id, n]));
const newSubNodes = [];

targets.forEach((t, id) => {
  const fullObj = id === centerNode.id ? centerNode : nodes[id];
  let existing = existingMap.get(id);

  if (!existing) {
    existing = {
      ...fullObj,
      sx: t.isCenter ? cx : cx + (Math.random() - 0.5) * 60,
      sy: t.isCenter ? cy : cy + (Math.random() - 0.5) * 60,
      currentSize: 4,
      targetSx: t.targetSx,
      targetSy: t.targetSy,
      targetSize: t.targetSize,
      activeDegree: t.activeDegree,
      isCenter: t.isCenter,
      interType: t.interType
    };
  } else {
    existing.targetSx = t.targetSx;
    existing.targetSy = t.targetSy;
    existing.targetSize = t.targetSize;
    existing.activeDegree = t.activeDegree;
    existing.isCenter = t.isCenter;
    existing.interType = t.interType;
  }
  newSubNodes.push(existing);
});

subState.nodes = newSubNodes;

const interactionTypes = [
  { name: 'Depredación', color: '#C96349' },
  { name: 'Herbivoría', color: '#84A48B' },
  { name: 'Dispersión', color: '#E69888' },
  { name: 'Mutualismo', color: '#E7C878' },
  { name: 'Nidificación', color: '#F79E70' },
  { name: 'Visita Floral', color: '#A386A9' },
  { name: 'Anidamiento', color: '#D1A996' },
  { name: 'Parasitismo', color: '#C6B3CA' },
  { name: 'Alelopatía', color: '#6B9080' }
];

function loopSub() {
  sctx.fillStyle = '#000000';
  sctx.fillRect(0, 0, subCanvas.width, subCanvas.height);

  // Smooth physics lerp transition towards new restructured positions
  subState.nodes.forEach(sn => {
    sn.sx += (sn.targetSx - sn.sx) * 0.12;
    sn.sy += (sn.targetSy - sn.sy) * 0.12;
    sn.currentSize += (sn.targetSize - sn.currentSize) * 0.12;
  });

  const subNodeMap = new Map(subState.nodes.map(n => [n.id, n]));

  // Draw Inter-Neighbor Decentralized Cross-Links first
  subState.nodes.forEach(snA => {
    if (!snA.neighbors) return;
