330:       const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
331:       const y2 = y * cosX - z1 * sinX;
332:       const z2 = y * sinX + z1 * cosX;
333: 
334:       const cx = x1 + panX;
335:       const cy = y2 + panY;
336: 
337:       const dist = 600;
338:       const scale = zoom / (z2 + dist);
339: 
340:       return {
341:         x: w / 2 + cx * scale,
342:         y: h / 2 + cy * scale,
343:         z: z2,
344:         scale,
345:         visible: (z2 + dist) > 10
346:       };
