370:     function project(x, y, z, w, h) {
371:       const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
372:       const x1 = x * cosY + z * sinY;
373:       const z1 = -x * sinY + z * cosY;
374: 
375:       const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
376:       const y2 = y * cosX - z1 * sinX;
377:       const z2 = y * sinX + z1 * cosX;
378: 
379:       const cx = x1 + panX;
380:       const cy = y2 + panY;
381: 
382:       const dist = 600;
383:       const scale = zoom / (z2 + dist);
384: 
385:       return {
386:         x: w / 2 + cx * scale,
387:         y: h / 2 + cy * scale,
388:         z: z2,
389:         scale,
390:         visible: (z2 + dist) > 10
391:       };
392:     }
